var n=`0019-kovbasa-domashnia`;var i=`world-0019`;var s=`UA`;var r=`eastern-europe`;var t=4;var o=58;var u={en:`Kovbasa Domashnia`,ua:`Домашня ковбаса`};var d={en:`Ready-made sausage from the catalog is roasted with garlic; fresh sausage production requires casing ingredients not currently included.`,ua:`Готову ковбасу з каталогу запікають із часником; для виготовлення сирої ковбаси потрібні оболонки, яких нині немає в каталозі.`};var g=[{en:`Pierce the prepared Ukrainian homemade sausage in several places, then rub with crushed garlic and pepper. This version uses ready-made sausage from the ingredient catalog.`,ua:`Злегка проколіть підготовлену домашню ковбасу в кількох місцях і натріть розчавленим часником та перцем. У цьому варіанті використовується вже готова ковбаса з каталогу.`,t:[`marinating`],m:20,i:[[`ukrainian-homemade-sausage`,700,`g`],[`garlic`,3,`clove`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roast in a 190°C oven until browned and heated thoroughly; turn once so the casing colors evenly.`,ua:`Запікайте при 190°C до рум’яності й повного прогрівання, один раз перевернувши для рівної скоринки.`,t:[`roasting`],m:35,i:[[`sunflower-oil`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`dijon-mustard`,35,`g`]]}];var l={slug:n,id:i,country:`UA`,region:r,servings:4,minutes:58,title:u,text:d,steps:g};export{s as country,l as default,i as id,o as minutes,r as region,t as servings,n as slug,g as steps,d as text,u as title};